@startuml

class Person {
  + firstName : string
  + lastName : string
  + birthDate : date
}

abstract class Role {}

class Trainer {
  + diploma : string
}

class Member {}

class ProspectiveMember {}

class Intern {}

class FitnessCenter {
  + name : string
  + address : string
}

class Room {
  + center : FitnessCenter
  + roomNumber : int
  + capacity : int
}

abstract class Session {
  + startDate : date
  + startHour : time
}

class IndividualSession extends Session {}

class GroupSession extends Session {
  + type : string
}

class Participation {
  + person : Person
  + session : Session
}

Trainer --|> Role
Member --|> Role
ProspectiveMember --|> Role
Intern --|> Role
Person "1" *-- "*" Role
FitnessCenter "1" *-- "*" Room
Room "0..*" -- "*" GroupSession
Room "0..*" -- "*" IndividualSession
GroupSession "1" -- "1" Trainer
Participation "*" -- "1" Person
Participation "*" -- "1" Session

@enduml

